// brainfuck2dir: brainfuck source as directory trees.
//
// The conversion logic itself is brainfuck (src/b2d.bf, embedded via
// @embedFile and generated by tools/gen_b2d.py). This file is only the
// boring part: CLI, input validation, and either printing the JSON
// scheme (transpile mode) or materializing it as a directory tree.

const std = @import("std");
const bfi = @import("bfi.zig");
const convert = @import("convert.zig");
const manifest = @import("manifest.zig");
const build_info = @import("build_info");

const version_text = "brainfuck2dir " ++ build_info.version ++ "\n";

const usage_text =
    \\Usage: b2d [OPTIONS] [FILE]
    \\
    \\Convert brainfuck source into a directory tree. Reads stdin by
    \\default; with FILE, reads that file. Non-command bytes are
    \\comments. Runs of a command become files, loops become
    \\directories:
    \\
    \\  +++++++++                     "001+": "009"
    \\  [->+<]                        "001loop": { ... }
    \\
    \\The conversion itself is a brainfuck program (b2d.bf) executed
    \\by the built-in interpreter. This binary is the VM.
    \\
    \\Options:
    \\  -o, --out <DIR>    Materialize into DIR instead of printing JSON.
    \\  -n, --dry-run      Validate and print the plan; write nothing.
    \\                      Only meaningful with --out.
    \\  -v, --verbose      Print one line per entry while applying.
    \\      --no-clobber   Fail instead of replacing existing entries.
    \\  -h, --help         Print this help and exit.
    \\  -V, --version      Print version and exit.
    \\
    \\Limits (rejected before the interpreter runs):
    \\  * NUL bytes in input (0 is the EOF marker on the brainfuck tape);
    \\  * unbalanced brackets;
    \\  * nesting deeper than 7400 loops;
    \\  * more than 999 entries per nesting level;
    \\  * a single command repeated more than 999 times in a row
    \\    (split into two entries instead -- that one is handled, not
    \\    rejected).
    \\
    \\Exit codes:
    \\  0  success
    \\  1  usage error
    \\  2  invalid brainfuck source
    \\  3  filesystem error
    \\
    \\
;

const max_input: u64 = 1 << 30; // 1 GiB of brainfuck is a lot of brainfuck

const max_depth: usize = 7400; // b2d.bf frame stack: 64 + 4*(7400+1) < 30000
const max_entries: usize = 999; // 3-digit sequence numbers

const Cli = struct {
    input: ?[]const u8 = null,
    out: ?[]const u8 = null,
    dry_run: bool = false,
    verbose: bool = false,
    force: bool = true,
};

fn printStdout(io: std.Io, comptime text: []const u8) void {
    std.Io.File.stdout().writeStreamingAll(io, text) catch {};
}

fn die(io: std.Io, code: u8, comptime fmt: []const u8, args: anytype) noreturn {
    var buf: [2048]u8 = undefined;
    var fw = std.Io.File.stderr().writer(io, &buf);
    const w = &fw.interface;
    w.print("b2d: " ++ fmt ++ "\n", args) catch {};
    w.flush() catch {};
    std.process.exit(code);
}

fn usageError(io: std.Io, comptime fmt: []const u8, args: anytype) noreturn {
    var buf: [4096]u8 = undefined;
    var fw = std.Io.File.stderr().writer(io, &buf);
    const w = &fw.interface;
    w.print("b2d: " ++ fmt ++ "\n\n", args) catch {};
    w.writeAll(usage_text) catch {};
    w.flush() catch {};
    std.process.exit(1);
}

fn parseCli(io: std.Io, args: std.process.Args) Cli {
    var cli = Cli{};
    var positional: ?[]const u8 = null;
    var no_more_flags = false;

    var it = std.process.Args.Iterator.init(args);
    _ = it.next(); // argv[0]

    while (it.next()) |arg| {
        if (no_more_flags or arg.len < 2 or arg[0] != '-') {
            if (positional != null) usageError(io, "unexpected extra argument '{s}'", .{arg});
            positional = arg;
            continue;
        }
        if (std.mem.eql(u8, arg, "--")) {
            no_more_flags = true;
            continue;
        }

        if (std.mem.eql(u8, arg, "-h") or std.mem.eql(u8, arg, "--help")) {
            printStdout(io, usage_text);
            std.process.exit(0);
        }
        if (std.mem.eql(u8, arg, "-V") or std.mem.eql(u8, arg, "--version")) {
            printStdout(io, version_text);
            std.process.exit(0);
        }
        if (std.mem.eql(u8, arg, "-n") or std.mem.eql(u8, arg, "--dry-run")) {
            cli.dry_run = true;
            continue;
        }
        if (std.mem.eql(u8, arg, "-v") or std.mem.eql(u8, arg, "--verbose")) {
            cli.verbose = true;
            continue;
        }
        if (std.mem.eql(u8, arg, "--no-clobber")) {
            cli.force = false;
            continue;
        }
        if (std.mem.eql(u8, arg, "-o") or std.mem.eql(u8, arg, "--out")) {
            const value = it.next() orelse usageError(io, "option '{s}' requires a value", .{arg});
            cli.out = value;
            continue;
        }
        if (std.mem.startsWith(u8, arg, "--out=")) {
            cli.out = arg["--out=".len..];
            continue;
        }

        usageError(io, "unknown option '{s}'", .{arg});
    }

    cli.input = positional;
    return cli;
}

fn isCommand(c: u8) bool {
    return switch (c) {
        '+', '-', '<', '>', '.', ',', '[', ']' => true,
        else => false,
    };
}

/// Structural validation, mirroring exactly what b2d.bf supports:
/// balanced brackets, a depth bound, an entries-per-level bound and
/// no NUL bytes (0 is the brainfuck EOF marker). Counts entries the
/// same way b2d.bf numbers them: a new entry starts on a command that
/// differs from the previous one, on a '[', and when a 999-run wraps.
const Validator = struct {
    depth: usize = 0,
    prev: [max_depth + 1]u8 = [_]u8{0} ** (max_depth + 1),
    run: [max_depth + 1]u32 = [_]u32{0} ** (max_depth + 1),
    entries: [max_depth + 1]u32 = [_]u32{0} ** (max_depth + 1),

    fn feed(self: *Validator, io: std.Io, c: u8) void {
        switch (c) {
            0 => die(io, 2, "NUL byte in input: 0 is the interpreter's EOF marker", .{}),
            '[' => {
                self.bump(io, self.depth);
                self.depth += 1;
                if (self.depth > max_depth) {
                    die(io, 2, "nesting deeper than {d} loops", .{max_depth});
                }
                self.prev[self.depth] = 0;
                self.run[self.depth] = 0;
            },
            ']' => {
                if (self.depth == 0) die(io, 2, "unbalanced ']'", .{});
                self.depth -= 1;
                self.prev[self.depth] = 0;
                self.run[self.depth] = 0;
            },
            '+', '-', '<', '>', '.', ',' => {
                const d = self.depth;
                if (self.prev[d] == c and self.run[d] < 999) {
                    self.run[d] += 1;
                } else {
                    self.bump(io, d);
                    self.prev[d] = c;
                    self.run[d] = 1;
                }
            },
            else => {}, // comment
        }
    }

    fn bump(self: *Validator, io: std.Io, d: usize) void {
        self.entries[d] += 1;
        if (self.entries[d] > max_entries) {
            die(io, 2, "more than {d} entries at nesting level {d}", .{ max_entries, d });
        }
    }

    fn finish(self: *Validator, io: std.Io) void {
        if (self.depth != 0) die(io, 2, "unbalanced '['", .{});
    }
};

fn readInput(io: std.Io, gpa: std.mem.Allocator, path: ?[]const u8) []u8 {
    if (path) |p| {
        if (!std.mem.eql(u8, p, "-")) {
            var f = std.Io.Dir.cwd().openFile(io, p, .{}) catch |e| {
                die(io, 3, "cannot open '{s}': {s}", .{ p, @errorName(e) });
            };
            defer f.close(io);
            var rbuf: [64 * 1024]u8 = undefined;
            var fr = f.readerStreaming(io, &rbuf);
            return fr.interface.allocRemaining(gpa, .limited(max_input)) catch |e| switch (e) {
                error.StreamTooLong => die(io, 3, "input exceeds the 1 GiB limit", .{}),
                else => die(io, 3, "cannot read '{s}': {s}", .{ p, @errorName(e) }),
            };
        }
    }
    const stdin = std.Io.File.stdin();
    var rbuf: [64 * 1024]u8 = undefined;
    var fr = stdin.readerStreaming(io, &rbuf);
    return fr.interface.allocRemaining(gpa, .limited(max_input)) catch |e| switch (e) {
        error.StreamTooLong => die(io, 3, "input exceeds the 1 GiB limit", .{}),
        else => die(io, 3, "cannot read stdin: {s}", .{@errorName(e)}),
    };
}

pub fn main(init: std.process.Init) !u8 {
    const io = init.io;
    const gpa = init.arena.allocator();

    const cli = parseCli(io, init.minimal.args);

    // ---- read + validate the brainfuck source ----------------------------

    const data = readInput(io, gpa, cli.input);

    var validator = Validator{};
    for (data) |c| validator.feed(io, c);
    validator.finish(io);

    // ---- run the brainfuck converter --------------------------------------

    const json = convert.transpile(gpa, data) catch |e| {
        die(io, 3, "internal: b2d.bf failed: {s}", .{@errorName(e)});
    };

    // ---- transpile mode: print the scheme and go home ---------------------

    if (cli.out == null) {
        const stdout = std.Io.File.stdout();
        stdout.writeStreamingAll(io, json) catch |e| {
            die(io, 3, "cannot write stdout: {s}", .{@errorName(e)});
        };
        stdout.writeStreamingAll(io, "\n") catch {};
        return 0;
    }

    // ---- materialize mode: JSON -> directory tree -------------------------

    const parsed = std.json.parseFromSlice(std.json.Value, gpa, json, .{}) catch |e| {
        die(io, 2, "internal: b2d.bf produced invalid JSON: {s}", .{@errorName(e)});
    };

    var out_dir: ?std.Io.Dir = std.Io.Dir.cwd().openDir(io, cli.out.?, .{}) catch null;

    if (out_dir == null and !cli.dry_run) {
        std.Io.Dir.cwd().createDirPath(io, cli.out.?) catch |e| {
            die(io, 3, "cannot create target directory '{s}': {s}", .{ cli.out.?, @errorName(e) });
        };
        out_dir = std.Io.Dir.cwd().openDir(io, cli.out.?, .{}) catch |e| {
            die(io, 3, "cannot open target directory '{s}': {s}", .{ cli.out.?, @errorName(e) });
        };
    }
    defer if (out_dir) |*d| d.close(io);

    var stdout_buffer: [8192]u8 = undefined;
    var stdout_writer = std.Io.File.stdout().writer(io, &stdout_buffer);
    const stdout = &stdout_writer.interface;

    manifest.materialize(io, gpa, out_dir, parsed.value, .{
        .force = cli.force,
        .dry_run = cli.dry_run,
        .verbose = cli.verbose,
        .plan = if (cli.dry_run or cli.verbose) stdout else null,
    }) catch |e| switch (e) {
        error.ManifestFailed => std.process.exit(2),
        else => std.process.exit(3),
    };

    try stdout.flush();
    return 0;
}

test {
    _ = @import("bfi.zig");
    _ = @import("manifest.zig");
    _ = @import("convert.zig");
}
